{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.base_product as with metafields as ( SELECT SPLIT_PART(t.id, \'/\', -1) AS id, case when left((v.value:sku::STRING),4) = \'4MCP\' then (v.value:sku::STRING) when left((v.value:sku::STRING),2) = \'BP\' then (v.value:sku::STRING) when left((v.value:sku::STRING),2) = \'SN\' then (v.value:sku::STRING) else REGEXP_REPLACE(v.value:sku::STRING, \'-[^-]*$\') end AS sku_group, MAX(t.producttype) AS category, MAX(t.status) AS status, MAX(t.title) AS title, MAX(t.tags) AS product_tags, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'occassion_new\', REPLACE(m.value:value, \'\"\',\'\'), NULL)) AS occassion, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'model\',REPLACE(REPLACE(m.value:value, \'\"\',\'\'),\'Model-\',\'\'), NULL)) AS model, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'designer\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) AS designer, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'print_design\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) AS print_design, case when lower(trim(MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'print_design\',REPLACE(m.value:value, \'\"\',\'\'), NULL)))) in (\'geometric, floral, printed\', \'printed, geometric\', \'abstract, embroidered\', \'geometric\', \'geometric, checks, printed\', \'printed, abstract\', \'abstract\', \'graphic print\', \'floral, animal print, abstract, printed\', \'geometric, abstract, printed\', \'geometric, embroidered, printed\', \'colourblocked, printed\', \'floral, printed\', \'geometric, printed\', \'abstract, marble, printed\', \'abstract, floral, printed\', \'animal print\', \'printed, tie & dye\', \'abstract, printed\', \'printed\', \'abstract, tie & dye, printed\', \'printed, floral\', \'colourblocked\', \'printed, polka dots\', \'floral\', \'abstract, geometric, printed\', \'printed, animal print\', \'tie & dye\', \'printed, graphic print\',\'printed, geometric\', \'printed\', \'graphic print, abstract, printed\', \'tie & dye\', \'geometric\', \'printed, graphic print\', \'graphic print\', \'printed, abstract\', \'abstract\', \'ombre\', \'animal print\', \'embroidered, graphic print\', \'abstract, printed\', \'graphic print, embroidered\', \'printed, abstract, printed\', \'graphic print,\', \'printed, polka dots\', \'camouflage\', \'printed, floral\', \'floral\', \'printed, animal print\', \'tye & dye\', \'graphic print, embroidered, printed\') THEN \'Printed\' WHEN lower(trim(MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'print_design\',REPLACE(m.value:value, \'\"\',\'\'), NULL)))) IN (\'embellished\', \'self-embroidered\', \'applique\', \'embroidered\') THEN \'Embroided\' WHEN lower(trim(MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'print_design\',REPLACE(m.value:value, \'\"\',\'\'), NULL)))) IN (\'plaid, checked\', \'checks, abstract\', \'self-design, geometric\', \'checks\', \'gingham\', \'checks, printed\', \'checks, stripes\', \'gingham, checks\', \'checks, geometric\', \'checks, floral, abstract, printed\') THEN \'Checks\' WHEN lower(trim(MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'print_design\',REPLACE(m.value:value, \'\"\',\'\'), NULL)))) IN (\'textured, stripes\', \'stripes\', \'stripes, printed\',\'stripes, textured\', \'stripes\', \'stripes, colourblocked\') THEN \'Stripes\' WHEN lower(trim(MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'print_design\',REPLACE(m.value:value, \'\"\',\'\'), NULL)))) IN (\'solid\', \'plain\') THEN \'Solid\' WHEN lower(trim(MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'print_design\',REPLACE(m.value:value, \'\"\',\'\'), NULL)))) IN (\'self-design, stripes\', \'self-design, tie & dye\', \'self-design, textured, plain\', \'textured, stripe\', \'textured, self-design\', \'self-design, textured\', \'textured\', \'self-design\', \'self-deign\', \'textured, geometric, self-design\', \'sefl-design\', \'self design\',\'textured, stripes\', \'self-design, textured, plain\', \'textured, self-design\', \'textured\', \'self-design, textured\', \'self-design\', \'self-design, knitted\') THEN \'Textured\' else \'Others\' end as print_design_mapped, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'collar\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) AS collar, CASE WHEN TRIM(LOWER(MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'collar\',REPLACE(m.value:value, \'\"\',\'\'), NULL)))) IN (\'mock\', \'spread\', \'cuban\', \'mandarin\', \'baseball\', \'high neck\', \'zip\',\'others\') THEN \'Others\' WHEN TRIM(LOWER(MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'collar\',REPLACE(m.value:value, \'\"\',\'\'), NULL)))) IN (\'v neck\', \'crew\',\'round\') THEN \'Round_neck\' ELSE collar END as collar_mapped, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) AS material, case when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Acrylic\', \'Acrylic Blend\') then \'acrylic\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Cotton Poly Blend\',\'Cotton\',\'Cotton\',\'Cotton Blend\') then \'cotton\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Faux suede\',\'faux leather\',\'Faux leather\',\'Faux Leather\') then \'faux\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Genuine Leather\',\'Synthetic leather\',\'Synthetic Leather\') then \'leather\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Linen\', \'Linen Blend\') then \'linen\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Lyocell Blend\',\'Lyocell\') then \'lyocell\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Marino Blend\') then \'marino\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Mesh\', \'Knit Mesh\',\'mesh textile\',\'Mesh fabric\') then \'mesh\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Modal Blend\', \'Modal\') then \'modal\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Nylon\', \'Nylon Blend\') then \'nylon\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Polyester\', \'Polyester Blend\',\'Poly Blend\') then \'polyster\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Rayon Blend\', \'Rayon\') then \'rayon\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Satin Blend\', \'Satin\') then \'satin\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'PU+Suede\', \'synthetic suede\',\'Synthetic suede\',\'Synthetic Suede\',\'Suede Leather & Mesh\',\'Suede\') then \'suede\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Synthetic\', \'Synthetic(Vegan Leather)\') then \'leather\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Tencel Blend\', \'Tencil\') then \'tencil\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Viscose Blend\', \'Viscose\') then \'viscose\' when MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) in (\'Terry Blend\') then \'terry\' else MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'material\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) end as material_mapped, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'sleeves_type\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) AS sleeves_type, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'fit\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) AS fit, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'style\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) AS style, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'closure\', REPLACE(m.value:value, \'\"\',\'\'), NULL)) AS closure, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'length\', REPLACE(m.value:value, \'\"\',\'\'), NULL)) AS length, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'vendor\', REPLACE(m.value:value, \'\"\',\'\'), NULL)) AS vendor, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'rise\', REPLACE(m.value:value, \'\"\',\'\'), NULL)) AS rise, MAX(IFF(REPLACE(m.value:key,\'\"\',\'\') = \'pocket\',REPLACE(m.value:value, \'\"\',\'\'), NULL)) AS pocket, MAX(IFF(TRY_TO_NUMBER(REPLACE(o.value:position, \'\"\',\'\')) = 1, REPLACE(REPLACE(REPLACE(o.value:values,\'[\',\'\'),\']\',\'\'),\'\"\',\'\'),NULL)) AS color FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql AS t, LATERAL FLATTEN(input => PARSE_JSON(t.variants)) AS v , LATERAL FLATTEN(input => t.metafields) AS m , LATERAL FLATTEN(input => t.options) AS o GROUP BY 1,2 ), segment_mapping_pre as ( select * from metafields qualify row_number() over (partition by sku_group order by product_tags desc ) = 1 ), metafield_mapping as ( select category, fit, collar, print_design, mapping from snitch_db.maplemonk.METAFIELD_metafield_mapping ), manual_pre as ( SELECT smp.*, mm.mapping AS mapping FROM segment_mapping_pre AS smp LEFT JOIN metafield_mapping AS mm ON CASE WHEN UPPER(TRIM(smp.category)) = \'SHIRTS\' THEN UPPER(CONCAT(\'SHIRTS|\', COALESCE(TRIM(smp.print_design_mapped), \'\'), \'|\', COALESCE(TRIM(smp.fit), \'\'))) WHEN UPPER(TRIM(smp.category)) = \'T-SHIRTS\' THEN UPPER(CONCAT(\'T-SHIRTS|\', COALESCE(TRIM(smp.print_design_mapped), \'\'), \'|\', COALESCE(TRIM(smp.fit), \'\'), \'|\', COALESCE(TRIM(smp.collar_mapped), \'\'))) WHEN UPPER(TRIM(smp.category)) = \'JEANS\' THEN UPPER(CONCAT(\'JEANS|\', COALESCE(TRIM(smp.fit), \'\'))) WHEN UPPER(TRIM(smp.category)) = \'TROUSERS\' THEN UPPER(CONCAT(\'TROUSERS|\', COALESCE(TRIM(smp.print_design_mapped), \'\'), \'|\', COALESCE(TRIM(smp.fit), \'\'))) WHEN UPPER(TRIM(smp.category)) = \'CARGO PANTS\' THEN UPPER(CONCAT(\'CARGO PANTS|\', COALESCE(TRIM(smp.fit), \'\'))) ELSE UPPER(CONCAT(UPPER(TRIM(smp.category)), \'|\', COALESCE(TRIM(smp.print_design_mapped), \'\'))) END = CASE WHEN UPPER(TRIM(mm.category)) = \'SHIRTS\' THEN UPPER(CONCAT(\'SHIRTS|\', COALESCE(TRIM(mm.print_design), \'\'), \'|\', COALESCE(TRIM(mm.fit), \'\'))) WHEN UPPER(TRIM(mm.category)) = \'T-SHIRTS\' THEN UPPER(CONCAT(\'T-SHIRTS|\', COALESCE(TRIM(mm.print_design), \'\'), \'|\', COALESCE(TRIM(mm.fit), \'\'), \'|\', COALESCE(TRIM(mm.collar), \'\'))) WHEN UPPER(TRIM(mm.category)) = \'JEANS\' THEN UPPER(CONCAT(\'JEANS|\', COALESCE(TRIM(mm.fit), \'\'))) WHEN UPPER(TRIM(mm.category)) = \'TROUSERS\' THEN UPPER(CONCAT(\'TROUSERS|\', COALESCE(TRIM(mm.print_design), \'\'), \'|\', COALESCE(TRIM(mm.fit), \'\'))) WHEN UPPER(TRIM(mm.category)) = \'CARGO PANTS\' THEN UPPER(CONCAT(\'CARGO PANTS|\', COALESCE(TRIM(mm.fit), \'\'))) ELSE UPPER(CONCAT(UPPER(TRIM(mm.category)), \'|\', COALESCE(TRIM(mm.print_design), \'\'))) END ), manual_sku_mapping as ( select sku_group, final from snitch_db.maplemonk.google_sheet_manual_mapping_metafield ), metafields_all as ( select a.*, b.final as manual_mapping, coalesce(b.final,a.mapping) as mapping_final from manual_pre a left join manual_sku_mapping b on a.sku_group = b.sku_group ), price as ( select distinct case when left((value:sku::STRING),4) = \'4MCP\' then (value:sku::STRING) when left((value:sku::STRING),2) = \'BP\' then (value:sku::STRING) when left((value:sku::STRING),2) = \'SN\' then (value:sku::STRING) else REGEXP_REPLACE(value:sku::STRING, \'-[^-]*$\') end AS sku_group, ifnull(value:compareAtPrice::NUMBER,0)::int as compare_at_price, value:price::NUMBER::int as price from snitch_db.maplemonk.new_meafields_product_products_graph_ql, lateral flatten(input => parse_json(variants)) as value ), final_price1 as ( select sku_group, greatest(compare_at_price,price) AS db_original_price, CASE WHEN compare_at_price != 0 THEN LEAST(compare_at_price,price) ELSE GREATEST(price,compare_at_price) END AS db_slashed_price from price ), final_price as ( select sku_group, db_original_price as original_price, db_slashed_price as current_slashed_price, from final_price1 where sku_group not in (\'\',\'1290\') qualify row_number() over (partition by sku_group order by db_original_price desc) = 1 ), live_date_pre as ( select case when left((value:sku::STRING),4) = \'4MCP\' then (value:sku::STRING) when left((value:sku::STRING),2) = \'BP\' then (value:sku::STRING) when left((value:sku::STRING),2) = \'SN\' then (value:sku::STRING) else REGEXP_REPLACE(value:sku::STRING, \'-[^-]*$\') end AS sku_group, min(PUBLISHEDAT::date) as live_date, lower(status) as status from snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => PARSE_JSON(variants)) AS value group by 1,3 ), sku_count as ( select sku_group, count(*) as status_count from live_date_pre group by 1 ), live_date_main as ( select upper(trim(a.sku_group)) as sku_group, a.status, live_date, row_number() over (partition by a.sku_group order by a.live_date desc) as rn, b.status_count from live_date_pre a left join sku_count b on a.sku_group = b.sku_group ), final_live_date_pre as ( select sku_group, status, live_date as final_live_date from live_date_main where (status_count > 1 and rn = 2) or (status_count = 1 and rn = 1) ), first_sales as ( select sku_group, min(order_timestamp::date) as first_order_date from snitch_db.maplemonk.fact_items_snitch group by 1 ), final_live_date as ( select a.sku_group, a.status, case when b.first_order_date is null then a.final_live_date when a.final_live_date is null then b.first_order_date else least(a.final_live_date,b.first_order_date) end as final_live_date, datediff(day,case when b.first_order_date is null then a.final_live_date when a.final_live_date is null then b.first_order_date else least(a.final_live_date,b.first_order_date) end,current_date) as days_since_live from final_live_date_pre a left join first_sales b on a.sku_group =b.sku_group ), sales_data as ( select case when UPPER(TRIM(a.sku_group)) like \'BP%\' then split_part(UPPER(TRIM(a.sku_group)),\'-\',0) else UPPER(TRIM(a.sku_group)) end as sku_group, ifnull(sum(case when type = \'Store\' then gross_quantity end),0) as store_quant, ifnull(sum(case when type = \'Shopify\' then gross_quantity end),0) as shopify_quant, ifnull(sum(case when type = \'Markteplace\' then gross_quantity end),0) as marketplace_quant, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=8 then gross_quantity end),0) as store_quant7, ifnull(sum(case when type = \'Store\' and date = current_date -1 then gross_quantity end),0) as store_quant1, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=8 then gross_quantity end),0)/7 as store_ros7, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=8 then gross_quantity end),0) as shopify_quant7, ifnull(sum(case when type = \'Shopify\' and date = current_date -1 then gross_quantity end),0) as shopify_quant1, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=8 then gross_quantity end),0)/7 as shopify_ros7, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=8 then gross_quantity end),0) as marketplace_quant7, ifnull(sum(case when type = \'Marketplace\' and date = current_date -1 then gross_quantity end),0) as marketplace_quant1, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=8 then gross_quantity end),0)/7 as marketplace_ros7, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=31 then gross_quantity end),0) as store_quant30, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=31 then gross_quantity end),0)/30 as store_ros30, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=31 then gross_quantity end),0) as shopify_quant30, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=31 then gross_quantity end),0)/30 as shopify_ros30, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=31 then gross_quantity end),0) as marketplace_quant30, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=31 then gross_quantity end),0)/30 as marketplace_ros30, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=8 then gross_sales end),0) as store_sales7, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=8 then gross_sales end),0) as shopify_sales7, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=8 then gross_sales end),0) as marketplace_sales7, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=31 then gross_sales end),0) as store_sales30, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=31 then gross_sales end),0) as shopify_sales30, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=31 then gross_sales end),0) as marketplace_sales30, ifnull(sum(case when type = \'Store\' then gross_sales end),0) as store_sales, ifnull(sum(case when type = \'Shopify\' then gross_sales end),0) as shopify_sales, ifnull(sum(case when type = \'Marketplace\' then gross_sales end),0) as marketplace_sales, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=8 then discount_amount end),0) as store_discount7, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=8 then discount_amount end),0) as shopify_discount7, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=8 then discount_amount end),0) as marketplace_discount7, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=31 then discount_amount end),0) as store_discount30, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=31 then discount_amount end),0) as shopify_discount30, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=31 then discount_amount end),0) as marketplace_discount30, ifnull(sum(case when type = \'Store\' then discount_amount end),0) as store_discount, ifnull(sum(case when type = \'Shopify\' then discount_amount end),0) as shopify_discount, ifnull(sum(case when type = \'Marketplace\' then discount_amount end),0) as marketplace_discount, ifnull(sum(case when type = \'Marketplace\' and datediff(day,b.final_live_date,date) <=31 then gross_quantity end),0) as marketplace_quant_first30, ifnull(sum(case when type = \'Shopify\' and datediff(day,b.final_live_date,date) <=31 then gross_quantity end),0) as shopify_quant_first30, ifnull(sum(case when type = \'Marketplace\' and datediff(day,b.final_live_date,date) <=61 then gross_quantity end),0) as marketplace_quant_first60, ifnull(sum(case when type = \'Shopify\' and datediff(day,b.final_live_date,date) <=61 then gross_quantity end),0) as shopify_quant_first60 from snitch_db.maplemonk.horizontal_sales_categories a left join final_live_date b on case when UPPER(TRIM(a.sku_group)) like \'BP%\' then split_part(UPPER(TRIM(a.sku_group)),\'-\',0) else UPPER(TRIM(a.sku_group)) end = upper(trim(b.sku_group)) group by 1 ), aging as ( select upper(trim(SKU_GROUP)) as sku_group, ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'0-30\') then units_on_hand end),0) as \"inv<30\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'60-90\',\'90-120\',\'120-150\',\'150-180\',\'180-210\',\'210-240\',\'240-270\',\'270-300\',\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>60\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'90-120\',\'120-150\',\'150-180\',\'180-210\',\'210-240\',\'240-270\',\'270-300\',\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>90\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'120-150\',\'150-180\',\'180-210\',\'210-240\',\'240-270\',\'270-300\',\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>120\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'180-210\',\'210-240\',\'240-270\',\'270-300\',\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>180\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'240-270\',\'270-300\',\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>240\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>300\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'>360\') then units_on_hand end),0) as \"inv>360\", ifnull(sum(units_on_hand),0) as units_on_hand, round(sum(\"Days in warehouse\"*units_on_hand)/sum(units_on_hand),0) as overall_aging from snitch_db.maplemonk.overall_aging group by 1 ), clicks as ( select upper(trim(sku_group)) as sku_group, sum(case when datediff(day,ga_date,current_date) <=8 then clicks end) clicks_7, sum(case when datediff(day,ga_date,current_date) <=31 then clicks end) clicks_30 from snitch_db.maplemonk.clicks_itemid group by 1 ), design as ( select upper(trim(sku_group)) as sku_group, case when div0(FIRST_30D_SALES,INVENTORY) < 0.3 and HIT_SIZES < 3 then \'hit\' else \'non_hit\' end as strike, inventory as starting_inventory from snitch_db.maplemonk.design_fact_items qualify row_number() over (partition by upper(trim(sku_group)) order by starting_inventory desc) = 1 ), inwards as ( select upper(trim(LEFT(\"Item Type skuCode\", LENGTH(\"Item Type skuCode\") - CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\"))))) AS sku_group, putaway_updated::date as inward_date, sum(putaway_completed_quantity) as inward_quantity from snitch_db.maplemonk.putaway_tracking where final_type = \'New Inward\' group by 1,2 having