overall_aging, (clicks_7/7)::int as clicks_7, (clicks_30/30)::int as clicks_30, g.strike, g.starting_inventory, h.inward_count, h.total_inwards, h.last_inward, h.days_since_inward, i.shopify_return_quant, i.shopify_return_30, i.shopify_return_7, j.cost_price, k.image_url, online_available_sizes, online_inventory, online_XS_units, online_S_units, online_M_units, online_L_units, online_XL_units, online_XXL_units, online_XL3_units, online_XL4_units, online_XL5_units, online_XL6_units, online_XL7_units, online_XL8_units, no_of_stores, offline_inventory, offline_XS_UNITS, offline_S_UNITS, offline_M_UNITS, offline_L_UNITS, offline_XL_UNITS, offline_XXL_UNITS, offline_XL3_UNITS, offline_XL4_UNITS, offline_XL5_UNITS, offline_XL6_UNITS, offline_JIT_XS_UNITS, offline_JIT_S_UNITS, offline_JIT_M_UNITS, offline_JIT_L_UNITS, offline_JIT_XL_UNITS, offline_JIT_2XL_UNITS, offline_JIT_3XL_UNITS, offline_JIT_4XL_UNITS, offline_JIT_5XL_UNITS, offline_JIT_6XL_UNITS, case when shopify_ros7+marketplace_ros7+store_ros7 >= 15 then \'head\' when days_since_live <= 30 then \'new\' when shopify_ros7+marketplace_ros7+store_ros7 > 5 then \'belly\' else \'tail\' end as sku_class, case when lower(a.sku_group) like \'4mbg%\' then \'plus_size\' when lower(style) like \'%luxe%\' then \'luxe\' when lower(style) like \'%core%\' then \'core\' when lower(category) in (\'perfumes\',\'accessories\',\'bags\',\'belts\',\'sunglasses\',\'shoes\',\'slip-ons\') then \'long_tail\' else \'Snitch\' end as l1_category from metafields_all a left join final_price b on a.sku_group = b.sku_group left join final_live_date c on a.sku_group = c.sku_group left join sales_data d on a.sku_group = d.sku_group left join aging e on a.sku_group = e.sku_group left join clicks f on a.sku_group = f.sku_group left join design g on a.sku_group = g.sku_group left join inwards_data h on a.sku_group = h.sku_group left join returns i on a.sku_group = i.sku_group left join cost_price j on a.sku_group = j.sku_group left join images k on a.sku_group = k.sku_group left join final_inventory l on a.sku_group = l.sku_group where category not in (\'Gift Cards\',\'Carry_Bags\',\'\') ), cat_class as ( select category, (PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY shopify_ros7+marketplace_ros7+store_ros7)) AS head, (PERCENTILE_CONT(0.40) WITHIN GROUP (ORDER BY shopify_ros7+marketplace_ros7+store_ros7)) AS belly from base_table where online_available_sizes = num_sizes group by 1 ) select a.*, case when shopify_ros7+marketplace_ros7+store_ros7 >= head then \'head\' when days_since_live <= 30 and shopify_ros7+marketplace_ros7+store_ros7 = 0 then \'new_not_sold\' when days_since_live <= 30 then \'new\' when shopify_ros7+marketplace_ros7+store_ros7 > belly then \'belly\' when online_available_sizes <> num_sizes then \'cut_size\' else \'tail\' end as cat_sku_class from base_table a join cat_class b on a.category = b.category ;",
                    "transaction": true
